import java.util.*;

public class ExerciseVerifier {
  public List<String> verify(Class<?> cls, String baseUrl) throws Exception {
    List<String> fails = new ArrayList<>();
    Object c = cls.getDeclaredConstructor().newInstance();
    int bad = (Integer) cls.getMethod("check", String.class, String.class).invoke(c, baseUrl, "bad");
    int noRole = (Integer) cls.getMethod("check", String.class, String.class).invoke(c, baseUrl, "no-role");
    int admin = (Integer) cls.getMethod("check", String.class, String.class).invoke(c, baseUrl, "admin");
    if (bad != 401) fails.add("expected 401 got " + bad);
    if (noRole != 403) fails.add("expected 403 got " + noRole);
    if (admin != 200) fails.add("expected 200 got " + admin);
    return fails;
  }
}
